///
/// Community: `empty` without room objects, `normal` with a spawn in a room whose controller the player owns, `lost` otherwise.
#[derive(Clone, Copy, Debug, Default, PartialEq, Eq)]
pub struct UserWorldStatus;

impl Endpoint for UserWorldStatus {
    type Response = types::UserWorldStatusResponse;
    const METHOD: Method = Method::GET;
    const PATH: &'static str = "api/user/world-status";
    const AUTH: Auth = Auth::Required;
    const FORMAT: Format = Format::Envelope;
}

/// `GET /api/version`: Read server capabilities.
///
/// Reports protocol and server capabilities. The official web client fetches it without credentials to configure itself (history chunk size, renderer resources, feature menu). Official responses carry `features` with optional `menuData` and `shards`; the client falls back to the market and auth features when `serverData.features` is absent.
///
/// Community: Returns `protocol: 14`, `useNativeAuth`, `users` (active non-bot accounts with CPU), `serverData` (`welcomeText`, `customObjectTypes`, `historyChunkSize`, `socketUpdateThrottle`, `renderer`, as configured by mods) and `packageVersion` (the installed `screeps` package version, when resolvable). Stock backend-local sends neither `serverData.features` nor `serverData.shards`, so the official client falls back to its market/auth feature set and shows no shard names.
#[derive(Clone, Copy, Debug, Default, PartialEq, Eq)]
pub struct PlatformVersion;

impl Endpoint for PlatformVersion {
    type Response = types::PlatformVersion;
    const METHOD: Method = Method::GET;
    const PATH: &'static str = "api/version";
    const AUTH: Auth = Auth::None;
    const FORMAT: Format = Format::Envelope;
}

/// `GET /room-history`: Read private-server room-history chunk.
///
/// Room-history chunk endpoint of the private-server protocol. When `options.official` is false the official web client requests `http://<host>:<port>/room-history?room=<room>&time=<tick>` with `time` aligned to `serverData.historyChunkSize`, treats any non-200 status as missing and fills `room` when absent. backend-local passes `room` and `time` unvalidated to `config.backend.onGetRoomHistory` and sends its result, or its error with HTTP 500.
///
/// Community: Stock backend-local keeps no room history: its default provider answers every request with HTTP 500 `text/html` `not implemented`. A mod that stores history replaces `config.backend.onGetRoomHistory`; whatever it returns is sent as the body.
#[derive(Clone, Debug, PartialEq)]
pub struct PlatformRoomHistory {
    /// Room name.
    pub room: String,
    /// Base game tick, normally aligned to the advertised `historyChunkSize`.
    pub time: u64,
}

impl Endpoint for PlatformRoomHistory {
    type Response = types::PlatformHistory;
    const METHOD: Method = Method::GET;
    const PATH: &'static str = "room-history";
    const AUTH: Auth = Auth::None;
    const FORMAT: Format = Format::Json;

    fn query(&self, query: &mut Query<'_>) {
        query.pair("room", &self.room);
        query.pair("time", &self.time.to_string());
    }
}
